CREATE USER developer WITH PASSWORD 'developer';
ALTER USER developer WITH SUPERUSER;
CREATE DATABASE db_postgres;
ALTER DATABASE db_postgres OWNER TO developer;

CREATE TABLE employed (
                          id                 BIGSERIAL    PRIMARY KEY ,
                          industry           TEXT,
                          major_occupation   TEXT,
                          minor_occupation   TEXT,
                          race_gender        TEXT,
                          industry_total     DOUBLE PRECISION,
                          employ_n           DOUBLE PRECISION,
                          year               INTEGER
);

CREATE TABLE earn (
                      id                    BIGSERIAL    PRIMARY KEY,
                      sex                   TEXT,
                      race                  TEXT,
                      ethnic_origin	        TEXT,
                      age                   TEXT,
                      year                  INTEGER,
                      quarter               INTEGER,
                      n_persons             INTEGER,
                      median_weekly_earn    INTEGER
);

